import{_ as t,o as e,c as o,a3 as n}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"3.0 配平，自适应，最大价值产出，叽里咕噜说什么呢","description":"","frontmatter":{"translationSource":{"title":"3.0 配平，自适应，最大价值产出，叽里咕噜说什么呢","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=lZhn9NxeSAXQ7W0ANuqKFR","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about"}]]},"headers":[],"relativePath":"zh/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about.md","filePath":"zh/page-lZhn9NxeSAXQ7W0ANuqKFR.md"}'),i={name:"zh/3-0-balancing-adaptation-maximum-value-output-what-are-you-talking-about.md"};function l(r,a,p,u,s,d){return e(),o("div",null,[...a[0]||(a[0]=[n('<div class="logistics-content"><span class="logistics-source-anchor" id="_3-0-配平-自适应-最大价值产出-叽里咕噜说什么呢" aria-hidden="true"></span><h1 id="_3-0-配平-自适应-最大价值产出-叽里咕噜说什么呢" tabindex="-1">3.0 配平，自适应，最大价值产出，叽里咕噜说什么呢 <a class="header-anchor" href="#_3-0-配平-自适应-最大价值产出-叽里咕噜说什么呢" aria-label="Permalink to &quot;3\\.0 配平，自适应，最大价值产出，叽里咕噜说什么呢&quot;">​</a></h1><blockquote><p>源页面 ID：<code>lZhn9NxeSAXQ7W0ANuqKFR</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=lZhn9NxeSAXQ7W0ANuqKFR" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>什么是<span class="mark-orange"><strong>配平</strong></span>：给定原材料供应量，设计产线使得原材料全部稳定的被消耗（至少经过一步加工）</p><p>**阻塞生产/自适应是达成配平的一种手段，但并不是唯一手段。**硬分流也能直接达到配平，使用时钟信号震荡重息壤生产也能达到配平。</p><p>自适应也并非仅仅是为了配平。我们前面已经给出了很多例子了。</p><p>两种配方通过阻塞生产/自适应配平，是<strong>平衡型阻塞</strong>的体现。其中一种产物满仓后，变成另外两种配方自适应配平，这一过程是<strong>切换型阻塞</strong>的体现。它们在根源上都是利用了<strong>不同位置</strong>的阻塞信号</p><p>**以上讨论仅涉及把原料消耗做成成品，并不牵扯到价值体系。**一般来说，加工后的产物价值总是高于原材料直接卖掉的价值，否则就没必要加工了。进一步地，加工后的产物价值需要相对合理，才能说配平生产某些产物，使得原材料全消耗时产出价值最高。否则，比如灼铜零件价格巨tm高，还会出现铜全部做灼铜，直接卖掉多余的息壤的产出价值高于配平的情形。当然，现在并不是这样的。</p><p>目前没有任何机制能够让产线能够自适应产出调度券最大的方案，只有人来根据要求规划好了生产方案产能再进行实现。就目前的简单情况，基本都是直接通过简单线性规划得出产能最大或净产能最大，或者满足更多限制情况下的产能最大等的具体生产方案（拿xxx原料做xxx产品），具体如何做到这一生产方案，则有直接分流分配，自适应等路线之分。</p><p><a href="/endfield-skydoc/zh/3-1-the-beginnings-of-automatic-balancing-xiranite-and-originium-powders">3.1 自动配平思想的萌芽：息壤与源石粉末的爱恨情仇</a></p><p>根据Cipolla的指导，一种较严格的定义如下</p><ul><li><p>精确分流生产：存在一个正整数组成的向量N，若当前生产线的缓存向量（因为有很多个生产线的缓存嘛）增加到N，则机器处永不发生阻塞。</p></li><li><p>阻塞生产/自动匹配：对任意正整数向量N，若当前生产线的缓存增加到N，则总能找到时间T，当t&gt;T时机器处发生阻塞</p></li></ul></div>',1)])])}const g=t(i,[["render",l]]);export{c as __pageData,g as default};
